   284:  left: 14px;
   285:  right: 14px;
   286:  bottom: max(8px, env(safe-area-inset-bottom));
   287:  height: 114px;
   288:  border-radius: var(--radius-8xl) var(--radius-8xl) 24px 24px;
   289:  background: var(--color-surface-dock);
   290:  box-shadow: var(--shadow-dock);
   291:}
