   293:.bottom-nav {
   294:  position: fixed;
   295:  z-index: 30;
   296:  bottom: max(24px, calc(env(safe-area-inset-bottom) + 12px));
   297:  left: 30px;
   298:  transform: none;
   299:  width: min(250px, calc(100vw - 122px));
