   311:.bottom-nav button { width: 68px; height: 58px; display: grid; place-items: center; gap: 0; border: 0; border-radius: var(--radius-full); color: var(--color-text-nav-inactive); background: transparent; cursor: pointer; }
   312:.bottom-nav button span { font-size: var(--font-size-xs); font-weight: var(--font-weight-black); }
   313:.bottom-nav button.active { color: var(--color-text-nav-active); background: white; box-shadow: var(--shadow-nav-active); }
   314:.add-button { position: fixed; z-index: 31; right: 29px; bottom: max(26px, calc(env(safe-area-inset-bottom) + 14px)); width: 68px; height: 68px; display: grid; place-items: center; border: 0; border-radius: var(--radius-full); color: white; background: var(--color-action-add); box-shadow: var(--shadow-add); cursor: pointer; }
   315:.companion-button svg { fill: currentColor; stroke-width: 1.4; }
   316:.woof-bubble { position: fixed; z-index: 32; right: 23px; bottom: max(100px, calc(env(safe-area-inset-bottom) + 88px)); padding: 6px 10px; border-radius: 12px 12px 3px 12px; color: #24372d; background: white; box-shadow: var(--shadow-woof); font-size: var(--font-size-sm); font-weight: var(--font-weight-black); transform: rotate(-4deg); }
   317:
   318:/* ═══════════════════════════════════════════════════════════════════════
   319:   Full card (shared by sub-screens)
   320:   ═══════════════════════════════════════════════════════════════════════ */
   321:.full-card { top: 126px; bottom: 132px; overflow-y: auto; padding-bottom: 26px; scrollbar-width: none; }
   322:.full-card::-webkit-scrollbar { display: none; }
   323:.back-button { display: flex; align-items: center; gap: 5px; margin: -5px 0 22px -5px; padding: 5px; border: 0; color: var(--color-text-back); background: transparent; font-weight: var(--font-weight-bold); cursor: pointer; }
   324:.supporting { max-width: 430px; margin: 10px 0 22px; color: var(--color-text-body); font-size: var(--font-size-lg); line-height: 1.45; }
   325:.score-orb { flex: none; display: grid; place-items: center; width: 57px; height: 57px; border-radius: var(--radius-full); color: #204a36; background: var(--color-accent-score); font-weight: var(--font-weight-black); }
   326:
   327:/* ═══════════════════════════════════════════════════════════════════════
   328:   Alert / next-dose / section title / care grid
   329:   ═══════════════════════════════════════════════════════════════════════ */
   330:.alert-card, .next-dose { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 13px; padding: 15px; border-radius: var(--radius-5xl); }
   331:.alert-card.warm { background: var(--color-surface-cream-warm); }
   332:.alert-card small, .next-dose small, .field small { color: #9e664e; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   333:.section-title { display: flex; justify-content: space-between; align-items: center; margin: 22px 2px 12px; }
   334:.section-title h3 { margin: 0; font-size: var(--font-size-2xl); font-weight: var(--font-weight-black); }
   335:.section-title button, .section-title span { border: 0; color: var(--color-text-body); background: transparent; font-size: var(--font-size-md); font-weight: var(--font-weight-bold); }
   336:.care-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
   337:.care-grid article { display: grid; gap: 5px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-sage); }
   338:.care-grid article span { color: #5c8069; }
   339:.care-grid strong { font-size: var(--font-size-5xl); font-weight: var(--font-weight-black); }
   340:.care-grid small { color: var(--color-text-body); font-size: var(--font-size-sm); }
   341:
   342:/* ═══════════════════════════════════════════════════════════════════════
   343:   Activity card / role strip
   344:   ═══════════════════════════════════════════════════════════════════════ */
   345:.activity-card { margin-top: 10px; padding: 15px; border: 1px solid var(--color-border-card); border-radius: var(--radius-3xl); }
   346:.activity-card p { margin: 0; color: var(--color-text-body); font-size: var(--font-size-md); }
   347:.activity-card p:first-child { display: flex; justify-content: space-between; margin-bottom: 5px; color: #274538; }
   348:.role-strip { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 10px; margin-bottom: 12px; padding: 12px 14px; border-radius: var(--radius-3xl); color: #426653; background: var(--color-surface-sage-light); }
   349:.role-strip div { display: grid; }
   350:.role-strip small { color: #76847b; font-size: var(--font-size-sm); }
   351:.role-strip > span { padding: 5px 8px; border-radius: var(--radius-pill); color: #4f765e; background: white; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); }
   352:
   353:.next-dose { margin-top: 20px; background: var(--color-surface-sage-light); }
   354:.feature-icon.sage { color: var(--color-accent-sage-icon); background: var(--color-accent-sage-bg); }
