   379:.scanner { position: relative; width: 100%; min-height: 260px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; border: 0; border-radius: var(--radius-7xl); color: #345845; background: var(--color-surface-scanner); cursor: pointer; overflow: hidden; }
   380:.scanner::before { content: ""; position: absolute; inset: 0; opacity: .4; background: repeating-linear-gradient(0deg, transparent 0 24px, rgba(76,112,86,.08) 25px 26px); }
   381:.scanner strong, .scanner small, .camera-orb { z-index: 1; }
   382:.scanner small { color: var(--color-text-body); }
   383:.camera-orb { display: grid; place-items: center; width: 64px; height: 64px; border-radius: var(--radius-full); color: white; background: var(--color-primary-camera); box-shadow: var(--shadow-camera); }
   384:.scan-corner { position: absolute; width: 42px; height: 42px; border-color: var(--color-accent-scan-corner); }
   385:.top-left { top: 18px; left: 18px; border-top: 3px solid; border-left: 3px solid; border-radius: var(--radius-sm) 0 0; }
   386:.top-right { top: 18px; right: 18px; border-top: 3px solid; border-right: 3px solid; border-radius: 0 var(--radius-sm) 0 0; }
   387:.bottom-left { bottom: 18px; left: 18px; border-bottom: 3px solid; border-left: 3px solid; border-radius: 0 0 0 var(--radius-sm); }
   388:.bottom-right { bottom: 18px; right: 18px; border-right: 3px solid; border-bottom: 3px solid; border-radius: 0 0 var(--radius-sm); }
   389:.text-button { margin-top: 16px; padding: 10px; border: 0; color: #557463; background: transparent; font-weight: var(--font-weight-black); cursor: pointer; }
   390:.prescription-result { display: grid; gap: 12px; margin-top: 20px; text-align: left; }
   391:.prescription-result > .feature-icon { width: 54px; height: 54px; border-radius: var(--radius-3xl); margin: 0 auto 8px; }
   392:
   393:/* ═══════════════════════════════════════════════════════════════════════
   394:   Fields / proof
   395:   ═══════════════════════════════════════════════════════════════════════ */
   396:.field, .field-row { padding: 14px; border-radius: var(--radius-xl); background: var(--color-surface-sage); }
   397:.field { display: grid; gap: 3px; }
   398:.field small { color: #6e886f; }
   399:.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding: 0; background: transparent; }
   400:.proof-scanner.captured { color: #315a43; background: var(--color-surface-sage-darker); }
   401:.proof-check { z-index: 1; display: grid; place-items: center; width: 70px; height: 70px; border-radius: var(--radius-full); color: white; background: var(--color-accent-proof); box-shadow: var(--shadow-proof); }
   402:
   403:/* ═══════════════════════════════════════════════════════════════════════
   404:   Plain card / explain points / listen button
   405:   ═══════════════════════════════════════════════════════════════════════ */
   406:.plain-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; margin-top: 20px; padding: 16px; border-radius: var(--radius-6xl); background: var(--color-surface-cream-warm); }
   407:.plain-card h3 { margin: 2px 0 0; font-size: var(--font-size-4xl); }
   408:.plain-card small { color: #9d654d; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   409:.plain-card > button { width: 46px; height: 46px; display: grid; place-items: center; border: 0; border-radius: var(--radius-full); color: white; background: var(--color-action-stop); cursor: pointer; }
   410:.explain-points { display: grid; margin-top: 14px; border: 1px solid var(--color-border-explain); border-radius: var(--radius-5xl); overflow: hidden; }
   411:.explain-points article { padding: 13px 15px; border-bottom: 1px solid var(--color-border-explain); }
   412:.explain-points article:last-child { border: 0; }
   413:.explain-points strong { font-size: var(--font-size-base); }
   414:.explain-points p { margin: 3px 0 0; color: var(--color-text-body); font-size: var(--font-size-base); line-height: 1.4; }
   415:.listen-button { width: 100%; min-height: 46px; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 12px; border: 1px solid var(--color-border-listen); border-radius: var(--radius-xl); color: #496d59; background: #f4f6f0; font-weight: var(--font-weight-black); cursor: pointer; }
   416:
   417:/* ═══════════════════════════════════════════════════════════════════════
   418:   Schedule / dog message
   419:   ═══════════════════════════════════════════════════════════════════════ */
   420:.schedule-choice { display: grid; grid-template-columns: 72px 1fr auto; align-items: center; gap: 3px 10px; margin-top: 10px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-sage); }
   421:.schedule-choice span { grid-row: span 2; color: #6b7c70; font-size: var(--font-size-md); font-weight: var(--font-weight-black); text-transform: uppercase; }
   422:.schedule-choice strong { font-size: var(--font-size-4xl); }
   423:.schedule-choice small { color: var(--color-text-body); }
   424:.schedule-choice > svg { grid-column: 3; grid-row: 1 / span 2; }
   425:.dog-message { display: flex; align-items: center; gap: 12px; margin-top: 16px; padding: 13px; border-radius: var(--radius-3xl); color: #496a57; background: var(--color-surface-cream); }
   426:.dog-message p { margin: 0; color: #6f776f; font-size: var(--font-size-md); line-height: 1.4; }
   427:.dog-message strong { color: #4a594e; }
   428:
   429:/* ═══════════════════════════════════════════════════════════════════════
   430:   Walk screen
   431:   ═══════════════════════════════════════════════════════════════════════ */
   432:.walk-card { text-align: center; }
   433:.walk-card .back-button, .walk-card .eyebrow { text-align: left; }
   434:.walk-orb { width: 190px; height: 190px; margin: 23px auto; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; border: 10px solid var(--color-accent-walk-border-idle); border-radius: var(--radius-full); color: #446a55; background: #f2f5ed; transition: border-color .3s, transform .3s; }
   435:.walk-orb.active { border-color: var(--color-accent-walk-border); transform: scale(1.02); }
   436:.walk-orb strong { color: #193c2e; font-size: var(--font-size-8xl); font-weight: var(--font-weight-black); }
   437:.walk-orb small { color: #75847a; font-size: var(--font-size-sm); }
   438:.walk-stats { display: grid; grid-template-columns: repeat(3, 1fr); margin: 0 0 8px; }
   439:.walk-stats div { display: grid; gap: 2px; border-right: 1px solid #e0e5dc; }
   440:.walk-stats div:last-child { border: 0; }
   441:.walk-stats strong { font-size: var(--font-size-4xl); font-weight: var(--font-weight-black); }
   442:.walk-stats small { color: #79857e; font-size: var(--font-size-xs); text-transform: uppercase; }
   443:.stop-button { background: var(--color-action-stop); }
   444:.walk-note { color: #7b887f; font-size: var(--font-size-sm); }
   445:.gentle-note { margin: 8px auto 0; max-width: 330px; color: #88928b; font-size: var(--font-size-sm); line-height: 1.4; }
   446:
   447:/* ═══════════════════════════════════════════════════════════════════════
   448:   World card / customize / tricks
   449:   ═══════════════════════════════════════════════════════════════════════ */
   450:.world-card { position: relative; margin-top: 18px; padding: 22px; border-radius: var(--radius-7xl); color: white; background: linear-gradient(135deg, #4f7654, #8aa36d); overflow: hidden; }
   451:.world-card::after { content: ""; position: absolute; width: 150px; height: 150px; right: -40px; bottom: -85px; border: 18px solid rgba(255,255,255,.12); border-radius: var(--radius-full); }
   452:.world-card h3 { margin: 5px 0 2px; font-size: var(--font-size-6xl); }
   453:.world-card p { margin: 0; color: rgba(255,255,255,.78); font-size: var(--font-size-md); }
   454:.world-level { font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1.5px; }
   455:.world-progress { height: 7px; margin-top: 18px; border-radius: 9px; background: rgba(255,255,255,.22); overflow: hidden; }
   456:.world-progress span { display: block; width: 100%; height: 100%; border-radius: inherit; background: var(--color-accent-progress-bar); }
   457:.customize-row { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-top: 10px; padding: 11px; border: 0; border-radius: var(--radius-3xl); color: #315442; background: var(--color-surface-cream); text-align: left; cursor: pointer; }
   458:.customize-row div { display: grid; gap: 2px; }
   459:.customize-row small { color: #7b817b; font-size: var(--font-size-xs); }
   460:.trick-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
   461:.trick-grid article { display: grid; gap: 5px; padding: 15px; border: 1px dashed var(--color-border-trick); border-radius: var(--radius-5xl); color: #9aa29c; }
   462:.trick-grid article.earned { border: 0; color: #57735f; background: #e7efdf; }
   463:.trick-grid small { color: #818c84; font-size: var(--font-size-xs); }
   464:
   465:/* ═══════════════════════════════════════════════════════════════════════
   466:   Souvenir / screening / activity link
   467:   ═══════════════════════════════════════════════════════════════════════ */
   468:.souvenir-row, .screening-card { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; padding: 14px; border: 0; border-radius: var(--radius-4xl); color: #274538; background: var(--color-surface-cream); text-align: left; cursor: pointer; }
   469:.souvenir-row > span, .screening-card > span { display: grid; place-items: center; width: 52px; height: 52px; border-radius: var(--radius-xl); color: #9b653a; background: #ffdab0; font-size: var(--font-size-sm); font-weight: var(--font-weight-black); }
   470:.souvenir-row div, .screening-card div, .activity-link div { display: grid; }
   471:.souvenir-row small, .screening-card small, .activity-link small { color: #7a847c; font-size: var(--font-size-sm); }
   472:
   473:/* ═══════════════════════════════════════════════════════════════════════
   474:   Health / metric / weekly
   475:   ═══════════════════════════════════════════════════════════════════════ */
   476:.metric-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; margin-top: 18px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-cream); }
   477:.metric-card.complete { background: var(--color-surface-sage-deep); }
   478:.metric-card h3 { margin: 2px 0; font-size: var(--font-size-2xl); }
   479:.metric-card p { margin: 0; color: #78847c; font-size: var(--font-size-sm); }
   480:.metric-card small { color: #8b6b4e; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   481:.metric-card > button { min-width: 46px; height: 38px; display: grid; place-items: center; border: 0; border-radius: var(--radius-md); color: white; background: var(--color-primary-camera); font-size: var(--font-size-md); font-weight: var(--font-weight-black); cursor: pointer; }
   482:.weekly-card { margin: 12px 0; padding: 17px; border-radius: var(--radius-6xl); background: var(--color-surface-sage); }
   483:.weekly-card .card-heading { margin-bottom: 10px; }
   484:.weekly-card h3 { margin: 0; font-size: var(--font-size-3xl); }
   485:.weekly-card p { color: #6d7d73; font-size: var(--font-size-md); line-height: 1.5; }
   486:.weekly-card > strong { display: block; padding: 10px; border-radius: var(--radius-sm); color: #5d6f63; background: white; font-size: var(--font-size-sm); }
   487:.health-bubble { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-top: 10px; padding: 12px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); color: #294a3a; background: white; text-align: left; cursor: pointer; }
   488:.health-bubble div { display: grid; gap: 2px; }
   489:.health-bubble small { color: #7a847c; font-size: var(--font-size-sm); }
   490:.treatment-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-bottom: 10px; padding: 13px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); }
   491:.treatment-card div { display: grid; gap: 2px; }
   492:.treatment-card small { color: #7a847c; font-size: var(--font-size-sm); }
   493:.treatment-card button { padding: 7px 10px; border: 0; border-radius: var(--radius-xs); color: #4f6d5c; background: #e8efe4; font-size: var(--font-size-sm); font-weight: var(--font-weight-black); cursor: pointer; }
   494:.screening-card { margin-bottom: 10px; background: var(--color-surface-cream-warm); }
   495:.activity-link { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; padding: 13px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); color: #284538; text-decoration: none; }
   496:
   497:/* ═══════════════════════════════════════════════════════════════════════
   498:   Festival / summary
   499:   ═══════════════════════════════════════════════════════════════════════ */
   500:.festival-card { margin-top: 18px; padding: 30px 20px; border-radius: var(--radius-7xl); color: #31583f; background: linear-gradient(145deg, #ffe7b8, #f8c9a6); text-align: center; }
   501:.festival-card h3 { margin: 10px 0 4px; font-size: var(--font-size-5xl); }
   502:.festival-card p { margin: 0; color: #766d5f; font-size: var(--font-size-md); }
   503:.summary-score { display: flex; align-items: center; justify-content: space-between; margin-top: 18px; padding: 18px; border-radius: var(--radius-5xl); color: #31583f; background: var(--color-surface-sage-deep); }
   504:.summary-score strong { font-size: var(--font-size-5xl); }
   505:.summary-score span { font-size: var(--font-size-sm); font-weight: var(--font-weight-black); }
   506:.summary-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; margin-top: 10px; }
   507:.summary-grid article { display: grid; gap: 3px; padding: 14px; border-radius: var(--radius-2xl); background: var(--color-surface-fog); }
   508:.summary-grid strong { font-size: var(--font-size-4xl); }
   509:.summary-grid small { color: #79857d; font-size: var(--font-size-xs); }
   510:.doctor-question { display: flex; align-items: center; gap: 12px; margin-top: 10px; padding: 14px; border-radius: var(--radius-3xl); color: #805b46; background: var(--color-surface-cream); }
   511:.doctor-question small { font-size: var(--font-size-2xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   512:.doctor-question p { margin: 3px 0 0; font-size: var(--font-size-md); }
   513:
   514:/* ═══════════════════════════════════════════════════════════════════════
   515:   Settings
   516:   ═══════════════════════════════════════════════════════════════════════ */
   517:.settings-group { display: grid; gap: 9px; margin-top: 18px; }
   518:.settings-group > button { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; padding: 12px; border: 0; border-radius: var(--radius-3xl); color: #294a3a; background: var(--color-surface-sage); text-align: left; cursor: pointer; }
   519:.settings-group > button:nth-child(1) { background: var(--color-surface-cream-alt); }
   520:.settings-group button div { display: grid; gap: 2px; }
   521:.settings-group small { color: #78857c; font-size: var(--font-size-sm); }
   522:.settings-note { display: flex; align-items: center; gap: 12px; margin-top: 14px; padding: 13px; border-radius: var(--radius-2xl); color: #65766b; background: var(--color-surface-stone-alt); }
   523:.settings-note p { margin: 0; font-size: var(--font-size-sm); line-height: 1.4; }
   524:
   525:/* ═══════════════════════════════════════════════════════════════════════
   526:   World picker / wardrobe
   527:   ═══════════════════════════════════════════════════════════════════════ */
   528:.world-picker { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
   529:.world-picker > button { min-width: 0; display: grid; gap: 3px; padding: 6px 6px 9px; border: 2px solid transparent; border-radius: var(--radius-3xl); color: #345343; background: var(--color-surface-stone); text-align: left; cursor: pointer; }
   530:.world-picker > button.selected { border-color: var(--color-border-world-sel); background: var(--color-surface-sage-light); }
   531:.world-picker strong { padding-inline: 3px; overflow: hidden; font-size: var(--font-size-md); text-overflow: ellipsis; white-space: nowrap; }
   532:.world-picker small { padding-inline: 3px; overflow: hidden; color: var(--color-text-faint); font-size: var(--font-size-2xs); text-overflow: ellipsis; white-space: nowrap; }
   533:
   534:.world-thumb { position: relative; height: 58px; border-radius: var(--radius-md); overflow: hidden; }
   535:.world-thumb::before, .world-thumb::after, .world-thumb i { content: ""; position: absolute; display: block; }
   536:.flat .world-thumb { background: linear-gradient(#f7c78f 0 48%, #c98555 49% 52%, #e7d3b5 53%); }
   537:.flat .world-thumb::before { left: 13%; bottom: 9px; width: 62%; height: 24px; border-radius: var(--radius-sm) var(--radius-sm) 3px 3px; background: #8caa82; }
   538:.flat .world-thumb::after { right: 10px; top: 8px; width: 17px; height: 24px; border: 3px solid rgba(255,255,255,.8); }
   539:.garden .world-thumb { background: linear-gradient(#8dc8c1 0 46%, #6b9f5b 47% 70%, #89b662 71%); }
   540:.garden .world-thumb::before { left: 11px; top: 13px; width: 22px; height: 31px; border-radius: var(--radius-full); background: #3f7b47; box-shadow: 45px 7px 0 #e194a4; }
   541:.garden .world-thumb::after { left: 42%; bottom: 0; width: 16%; height: 31px; background: #d6bf83; clip-path: polygon(40% 0,60% 0,100% 100%,0 100%); }
   542:.kampung .world-thumb { background: linear-gradient(#f5a86e 0 48%, #617d47 49%); }
   543:.kampung .world-thumb::before { left: 24%; bottom: 9px; width: 54%; height: 27px; background: #e6c184; clip-path: polygon(50% 0,100% 35%,92% 35%,92% 100%,8% 100%,8% 35%,0 35%); }
   544:.kampung .world-thumb::after { left: 44%; bottom: 9px; width: 14%; height: 16px; background: #855943; }
   545:.wardrobe-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
   546:.wardrobe-grid button { display: grid; grid-template-columns: 45px 1fr; align-items: center; gap: 1px 8px; padding: 9px; border: 2px solid transparent; border-radius: var(--radius-2xl); color: #345343; background: var(--color-surface-stone); text-align: left; cursor: pointer; }
   547:.wardrobe-grid button.selected { border-color: var(--color-border-wardrobe-sel); background: var(--color-surface-cream-selected); }
   548:.wardrobe-grid button > span { grid-row: span 2; display: grid; place-items: center; width: 43px; height: 43px; border-radius: var(--radius-xl); color: #6b826f; background: white; }
   549:.wardrobe-grid strong { font-size: var(--font-size-sm); }
   550:.wardrobe-grid small { color: var(--color-text-faint); font-size: var(--font-size-2xs); }
   551:
   552:/* ═══════════════════════════════════════════════════════════════════════
   553:   Accessory marks (mini icons in wardrobe)
   554:   ═══════════════════════════════════════════════════════════════════════ */
   555:.accessory-mark { position: relative; display: block; width: 34px; height: 26px; }
   556:.mark-glasses i { position: absolute; top: 7px; width: 14px; height: 11px; border: 4px solid #27322b; border-radius: var(--radius-full); }
   557:.mark-glasses i:first-child { left: 0; }
   558:.mark-glasses i:last-child { right: 0; }
   559:.mark-glasses::after { content: ""; position: absolute; top: 12px; left: 14px; width: 7px; border-top: 3px solid #27322b; }
   560:.mark-hat::before { content: ""; position: absolute; left: 5px; top: 3px; width: 24px; height: 16px; border-radius: 15px 15px 3px 3px; background: #e4b85e; }
   561:.mark-hat::after { content: ""; position: absolute; left: 0; top: 17px; width: 34px; height: 7px; border-radius: var(--radius-full); background: #bd793f; }
   562:.mark-bandana::before { content: ""; position: absolute; left: 3px; top: 4px; width: 28px; height: 20px; background: #d75442; clip-path: polygon(0 0,100% 0,50% 100%); }
   563:
   564:/* ═══════════════════════════════════════════════════════════════════════
   565:   Pet accessories (full-size on the dog)
   566:   ═══════════════════════════════════════════════════════════════════════ */
   567:.pet-accessory { position: fixed; z-index: 1; left: 50%; pointer-events: none; }
   568:.accessory-glasses { top: 31%; width: 124px; height: 46px; transform: translateX(-50%) rotate(-2deg); }
   569:.accessory-glasses i { position: absolute; width: 51px; height: 36px; border: 8px solid #201f1d; border-radius: var(--radius-full); background: rgba(47,57,50,.48); box-shadow: inset 0 3px rgba(255,255,255,.25); }
   570:.accessory-glasses i:first-child { left: 5px; }
   571:.accessory-glasses i:last-child { right: 5px; }
   572:.accessory-glasses::after { content: ""; position: absolute; top: 15px; left: 53px; width: 19px; border-top: 7px solid #201f1d; }
   573:.accessory-hat { top: 24%; width: 150px; height: 70px; transform: translateX(-50%) rotate(3deg); }
   574:.accessory-hat::before { content: ""; position: absolute; left: 34px; top: 4px; width: 82px; height: 48px; border-radius: 50px 50px 8px 8px; background: repeating-linear-gradient(90deg,#e7bd65 0 5px,#d7a953 6px 8px); }
   575:.accessory-hat::after { content: ""; position: absolute; left: 0; bottom: 4px; width: 150px; height: 20px; border-radius: var(--radius-full); background: #c88143; box-shadow: inset 0 5px #f0ce79; }
   576:.accessory-bandana { top: 39%; width: 94px; height: 58px; transform: translateX(-50%); background: #d95543; clip-path: polygon(0 0,100% 0,50% 100%); filter: var(--shadow-bandana); }
   577:
   578:/* ═══════════════════════════════════════════════════════════════════════
   579:   Toast
   580:   ═══════════════════════════════════════════════════════════════════════ */
   581:.toast { position: fixed; z-index: 80; top: 98px; left: 50%; transform: translateX(-50%); width: max-content; max-width: calc(100vw - 32px); padding: 12px 18px; border-radius: var(--radius-pill); color: white; background: var(--color-toast-bg); box-shadow: var(--shadow-toast); font-size: var(--font-size-base); font-weight: var(--font-weight-bold); animation: toast-in .2s ease-out; }
   582:
   583:@keyframes toast-in { from { transform: translate(-50%, -10px); opacity: 0; } }
   584:
   585:/* ═══════════════════════════════════════════════════════════════════════
   586:   Responsive
