   362:.add-button { position: absolute; z-index: 31; right: 29px; bottom: max(26px, calc(env(safe-area-inset-bottom) + 14px)); width: 68px; height: 68px; display: grid; place-items: center; border: 0; border-radius: var(--radius-full); color: white; background: var(--color-action-add); box-shadow: var(--shadow-add); cursor: pointer; }
   363:.companion-button svg { fill: currentColor; stroke-width: 1.4; }
   364:.woof-bubble { position: absolute; z-index: 32; right: 23px; bottom: max(100px, calc(env(safe-area-inset-bottom) + 88px)); padding: 6px 10px; border-radius: 12px 12px 3px 12px; color: #24372d; background: white; box-shadow: var(--shadow-woof); font-size: var(--font-size-sm); font-weight: var(--font-weight-black); transform: rotate(-4deg); }
