   366:/* ═══════════════════════════════════════════════════════════════════════
   367:   Full card (shared by sub-screens)
   368:   ═══════════════════════════════════════════════════════════════════════ */
   369:/*
   370: * --ledge-space is set while the dog stands on this card's top edge (see useSceneGround).
   371: * The card is a fixed frame (white, rounded, padding kept) holding the back button; only .full-card__scroll scrolls,
   372: * so scrolled content is clipped inside the frame instead of running into the card's edge. (FullCard.tsx)
   373: */
   374:.full-card { top: calc(var(--top-bar-space) + var(--ledge-space, -12px)); display: flex; flex-direction: column; overflow: hidden; }
   375:.full-card > .back-button { flex: none; align-self: flex-start; }
   376:/* Spans the frame's side padding (negative margin + padding) so focus rings and shadows aren't clipped at the content edge. */
   377:.full-card__scroll { flex: 1 1 auto; min-height: 0; margin-inline: -20px; padding: 8px 20px; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: none; }
   378:.full-card__scroll::-webkit-scrollbar { display: none; }
   379:.back-button { display: flex; align-items: center; gap: 5px; margin: -5px 0 14px -5px; padding: 5px; border: 0; color: var(--color-text-back); background: transparent; font-weight: var(--font-weight-bold); cursor: pointer; }
   380:.streak-line { margin: 6px 0 0; color: var(--color-text-body); font-size: var(--font-size-lg); font-weight: var(--font-weight-bold); }
