   389:.alert-card small, .next-dose small, .field small { color: #9e664e; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   390:.section-title { display: flex; justify-content: space-between; align-items: center; margin: 22px 2px 12px; }
