   571:.treatment-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-bottom: 10px; padding: 13px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); }
   572:.treatment-card div { display: grid; gap: 2px; }
   573:.treatment-card small { color: #7a847c; font-size: var(--font-size-sm); }
   574:.treatment-card button { padding: 7px 10px; border: 0; border-radius: var(--radius-xs); color: #4f6d5c; background: #e8efe4; font-size: var(--font-size-sm); font-weight: var(--font-weight-black); cursor: pointer; }
   575:.screening-card { margin-bottom: 10px; background: var(--color-surface-cream-warm); }
   576:.activity-link { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; padding: 13px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); color: #284538; text-decoration: none; }
   577:
   578:/* ═══════════════════════════════════════════════════════════════════════
   579:   Festival / summary
   580:   ═══════════════════════════════════════════════════════════════════════ */
   581:.festival-card { margin-top: 18px; padding: 30px 20px; border-radius: var(--radius-7xl); color: #31583f; background: linear-gradient(145deg, #ffe7b8, #f8c9a6); text-align: center; }
   582:.festival-card h3 { margin: 10px 0 4px; font-size: var(--font-size-5xl); }
   583:.festival-card p { margin: 0; color: #766d5f; font-size: var(--font-size-md); }
   584:.summary-score { display: flex; align-items: center; justify-content: space-between; margin-top: 18px; padding: 18px; border-radius: var(--radius-5xl); color: #31583f; background: var(--color-surface-sage-deep); }
   585:.summary-score strong { font-size: var(--font-size-5xl); }
   586:.summary-score span { font-size: var(--font-size-sm); font-weight: var(--font-weight-black); }
   587:.summary-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; margin-top: 10px; }
   588:.summary-grid article { display: grid; gap: 3px; padding: 14px; border-radius: var(--radius-2xl); background: var(--color-surface-fog); }
   589:.summary-grid strong { font-size: var(--font-size-4xl); }
   590:.summary-grid small { color: #79857d; font-size: var(--font-size-xs); }
   591:.doctor-question { display: flex; align-items: center; gap: 12px; margin-top: 10px; padding: 14px; border-radius: var(--radius-3xl); color: #805b46; background: var(--color-surface-cream); }
   592:.doctor-question small { font-size: var(--font-size-2xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   593:.doctor-question p { margin: 3px 0 0; font-size: var(--font-size-md); }
   594:
   595:/* ═══════════════════════════════════════════════════════════════════════
   596:   Settings
   597:   ═══════════════════════════════════════════════════════════════════════ */
   598:.settings-group { display: grid; gap: 9px; margin-top: 18px; }
   599:.settings-group > button { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; padding: 12px; border: 0; border-radius: var(--radius-3xl); color: #294a3a; background: var(--color-surface-sage); text-align: left; cursor: pointer; }
   600:.settings-group > button:nth-child(1) { background: var(--color-surface-cream-alt); }
   601:.settings-group button div { display: grid; gap: 2px; }
   602:.settings-group small { color: #78857c; font-size: var(--font-size-sm); }
   603:.settings-note { display: flex; align-items: center; gap: 12px; margin-top: 14px; padding: 13px; border-radius: var(--radius-2xl); color: #65766b; background: var(--color-surface-stone-alt); }
   604:.settings-note p { margin: 0; font-size: var(--font-size-sm); line-height: 1.4; }
   605:
   606:/* ═══════════════════════════════════════════════════════════════════════
   607:   World picker / wardrobe
   608:   ═══════════════════════════════════════════════════════════════════════ */
   609:.world-picker { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
   610:.world-picker > button { min-width: 0; display: grid; gap: 3px; padding: 6px 6px 9px; border: 2px solid transparent; border-radius: var(--radius-3xl); color: #345343; background: var(--color-surface-stone); text-align: left; cursor: pointer; }
   611:.world-picker > button.selected { border-color: var(--color-border-world-sel); background: var(--color-surface-sage-light); }
   612:.world-picker strong { padding-inline: 3px; overflow: hidden; font-size: var(--font-size-md); text-overflow: ellipsis; white-space: nowrap; }
   613:.world-picker small { padding-inline: 3px; overflow: hidden; color: var(--color-text-faint); font-size: var(--font-size-2xs); text-overflow: ellipsis; white-space: nowrap; }
   614:
   615:.world-thumb { position: relative; height: 58px; border-radius: var(--radius-md); overflow: hidden; }
   616:.world-thumb::before, .world-thumb::after, .world-thumb i { content: ""; position: absolute; display: block; }
   617:.flat .world-thumb { background: linear-gradient(#f7c78f 0 48%, #c98555 49% 52%, #e7d3b5 53%); }
   618:.flat .world-thumb::before { left: 13%; bottom: 9px; width: 62%; height: 24px; border-radius: var(--radius-sm) var(--radius-sm) 3px 3px; background: #8caa82; }
   619:.flat .world-thumb::after { right: 10px; top: 8px; width: 17px; height: 24px; border: 3px solid rgba(255,255,255,.8); }
   620:.garden .world-thumb { background: linear-gradient(#8dc8c1 0 46%, #6b9f5b 47% 70%, #89b662 71%); }
   621:.garden .world-thumb::before { left: 11px; top: 13px; width: 22px; height: 31px; border-radius: var(--radius-full); background: #3f7b47; box-shadow: 45px 7px 0 #e194a4; }
   622:.garden .world-thumb::after { left: 42%; bottom: 0; width: 16%; height: 31px; background: #d6bf83; clip-path: polygon(40% 0,60% 0,100% 100%,0 100%); }
   623:.kampung .world-thumb { background: linear-gradient(#f5a86e 0 48%, #617d47 49%); }
   624:.kampung .world-thumb::before { left: 24%; bottom: 9px; width: 54%; height: 27px; background: #e6c184; clip-path: polygon(50% 0,100% 35%,92% 35%,92% 100%,8% 100%,8% 35%,0 35%); }
   625:.kampung .world-thumb::after { left: 44%; bottom: 9px; width: 14%; height: 16px; background: #855943; }
   626:.wardrobe-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
   627:.wardrobe-grid button { display: grid; grid-template-columns: 45px 1fr; align-items: center; gap: 1px 8px; padding: 9px; border: 2px solid transparent; border-radius: var(--radius-2xl); color: #345343; background: var(--color-surface-stone); text-align: left; cursor: pointer; }
   628:.wardrobe-grid button.selected { border-color: var(--color-border-wardrobe-sel); background: var(--color-surface-cream-selected); }
   629:.wardrobe-grid button > span { grid-row: span 2; display: grid; place-items: center; width: 43px; height: 43px; border-radius: var(--radius-xl); color: #6b826f; background: white; }
   630:.wardrobe-grid strong { font-size: var(--font-size-sm); }
   631:.wardrobe-grid small { color: var(--color-text-faint); font-size: var(--font-size-2xs); }
   632:
   633:/* ═══════════════════════════════════════════════════════════════════════
   634:   Accessory marks (mini icons in wardrobe)
   635:   ═══════════════════════════════════════════════════════════════════════ */
   636:.accessory-mark { position: relative; display: block; width: 34px; height: 26px; }
   637:.mark-glasses i { position: absolute; top: 7px; width: 14px; height: 11px; border: 4px solid #27322b; border-radius: var(--radius-full); }
   638:.mark-glasses i:first-child { left: 0; }
   639:.mark-glasses i:last-child { right: 0; }
   640:.mark-glasses::after { content: ""; position: absolute; top: 12px; left: 14px; width: 7px; border-top: 3px solid #27322b; }
   641:.mark-hat::before { content: ""; position: absolute; left: 5px; top: 3px; width: 24px; height: 16px; border-radius: 15px 15px 3px 3px; background: #e4b85e; }
   642:.mark-hat::after { content: ""; position: absolute; left: 0; top: 17px; width: 34px; height: 7px; border-radius: var(--radius-full); background: #bd793f; }
   643:.mark-flower::before { content: ""; position: absolute; left: 10px; top: 5px; width: 14px; height: 14px; border-radius: 50%; background: #e8a5c0; box-shadow: -4px 0 #d484a8, 4px 0 #d484a8, 0 -4px #d484a8, 0 4px #d484a8; }
   644:.mark-flower::after { content: ""; position: absolute; left: 14px; top: 9px; width: 6px; height: 6px; border-radius: 50%; background: #f5d76e; }
   645:
   646:/* ═══════════════════════════════════════════════════════════════════════
   647:   Pet accessories (full-size on the dog)
   648:   ═══════════════════════════════════════════════════════════════════════ */
   649:/* Rendered inside DogStage's body, so it moves with the dog.
   650:   Sizes and positions are driven by config/accessories.ts via CSS custom properties. */
   651:.pet-accessory {
   652:  position: absolute;
   653:  z-index: 1;
   654:  left: var(--acc-left, 50%);
   655:  top: var(--acc-top);
   656:  width: var(--acc-width);
   657:  height: var(--acc-height);
   658:  transform: translateX(-50%) rotate(var(--acc-rotate, 0deg));
   659:  pointer-events: none;
   660:}
   661:
   662:.accessory-glasses i {
   663:  position: absolute;
   664:  width: 41%;
   665:  height: 78%;
   666:  border: min(8px, 1.5cqw) solid #201f1d;
   667:  border-radius: var(--radius-full);
   668:  background: rgba(47,57,50,.48);
   669:  box-shadow: inset 0 3px rgba(255,255,255,.25);
   670:}
   671:.accessory-glasses i:first-child { left: 4%; }
   672:.accessory-glasses i:last-child { right: 4%; }
   673:.accessory-glasses::after {
   674:  content: "";
   675:  position: absolute;
   676:  top: 33%;
   677:  left: 43%;
   678:  width: 15%;
   679:  border-top: min(7px, 1.2cqw) solid #201f1d;
   680:}
   681:
   682:.accessory-hat::before {
   683:  content: "";
   684:  position: absolute;
   685:  left: 23%;
   686:  top: 6%;
   687:  width: 55%;
   688:  height: 69%;
   689:  border-radius: 999px 999px 8px 8px;
   690:  background: repeating-linear-gradient(90deg,#e7bd65 0 5px,#d7a953 6px 8px);
   691:}
   692:.accessory-hat::after {
   693:  content: "";
   694:  position: absolute;
   695:  left: 0;
   696:  bottom: 6%;
   697:  width: 100%;
   698:  height: 29%;
   699:  border-radius: var(--radius-full);
   700:  background: #c88143;
   701:  box-shadow: inset 0 5px #f0ce79;
   702:}
   703:
   704:.accessory-flower::before {
   705:  content: "";
   706:  position: absolute;
   707:  left: 20%;
   708:  top: 20%;
   709:  width: 60%;
   710:  height: 60%;
   711:  border-radius: 50%;
   712:  background: #e8a5c0;
   713:  box-shadow: -20% 0 #d484a8, 20% 0 #d484a8, 0 -20% #d484a8, 0 20% #d484a8;
   714:}
   715:.accessory-flower::after {
   716:  content: "";
   717:  position: absolute;
   718:  left: 35%;
   719:  top: 35%;
   720:  width: 30%;
   721:  height: 30%;
   722:  border-radius: 50%;
   723:  background: #f5d76e;
   724:}
