   726:/* ═══════════════════════════════════════════════════════════════════════
   727:   T2: Search bar, HSA results, medication edit, explanation links
   728:   ═══════════════════════════════════════════════════════════════════════ */
   729:.search-bar { display: flex; gap: 8px; margin-top: 16px; }
   730:.search-bar input { flex: 1; min-height: 48px; padding: 8px 12px; border: 1px solid var(--color-border-card); border-radius: var(--radius-xl); color: var(--color-text-base); font: inherit; }
   731:.search-bar input:focus { outline: 2px solid var(--color-focus); outline-offset: 1px; }
   732:.hsa-results { display: grid; gap: 6px; margin-top: 14px; text-align: left; }
   733:.hsa-result-row { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 8px; padding: 12px 14px; border: 0; border-radius: var(--radius-3xl); color: var(--color-text-heading); background: var(--color-surface-sage); text-align: left; cursor: pointer; }
   734:.hsa-result-row:hover { background: var(--color-surface-sage-dark); }
   735:.hsa-result-row strong { font-size: var(--font-size-lg); }
   736:.hsa-result-row small { display: block; color: var(--color-text-body); font-size: var(--font-size-sm); }
   737:.hsa-credit { margin-top: 12px; color: var(--color-text-faint); font-size: var(--font-size-xs); line-height: 1.4; text-align: left; }
   738:.no-results { text-align: center; margin-top: 18px; }
   739:.no-results p { color: var(--color-text-body); font-size: var(--font-size-lg); }
   740:.error-text { margin-top: 8px; color: var(--color-action-stop); font-size: var(--font-size-sm); font-weight: 700; }
   741:.field-hint { color: var(--color-text-faint) !important; font-size: var(--font-size-xs) !important; font-weight: 400 !important; letter-spacing: 0 !important; }
   742:.field input { min-height: 44px; padding: 6px 10px; border: 1px solid var(--color-border-card); border-radius: var(--radius-lg); color: var(--color-text-base); font: inherit; }
   743:.field input:focus { outline: 2px solid var(--color-focus); outline-offset: 1px; }
   744:
   745:/* Medication list and edit on /care */
   746:.medication-list { display: grid; gap: 6px; }
   747:.medication-edit-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 12px 14px; border-radius: var(--radius-3xl); background: var(--color-surface-sage); }
   748:.medication-edit-row strong { font-size: var(--font-size-lg); }
   749:.medication-edit-row small { color: var(--color-text-body); font-size: var(--font-size-sm); }
   750:.medication-edit-form { display: grid; gap: 6px; width: 100%; }
   751:.medication-edit-form label { color: var(--color-text-body); font-size: var(--font-size-sm); font-weight: 700; }
   752:.medication-edit-form input { min-height: 44px; padding: 6px 10px; border: 1px solid var(--color-border-card); border-radius: var(--radius-lg); color: var(--color-text-base); font: inherit; }
   753:.edit-actions { display: flex; gap: 8px; margin-top: 4px; }
   754:.edit-actions .primary-button { margin-top: 0; min-height: 40px; flex: 1; }
   755:.edit-actions .text-button { margin-top: 0; }
   756:
   757:/* Explanation links and credits */
   758:.explanation-links { margin-top: 16px; display: grid; gap: 8px; }
   759:.source-credit { color: var(--color-text-faint); font-size: var(--font-size-xs); margin: 0; }
   760:.external-link { display: flex; align-items: center; gap: 6px; padding: 10px 12px; border: 1px solid var(--color-border-card); border-radius: var(--radius-xl); color: var(--color-text-heading); text-decoration: none; font-size: var(--font-size-sm); font-weight: 700; }
   761:.external-link:hover { background: var(--color-surface-sage); }
   762:
   763:/* Schedule choices with time inputs */
   764:.schedule-choice input[type="time"] { min-height: 44px; padding: 6px 8px; border: 0; border-radius: var(--radius-md); color: var(--color-text-heading); font: inherit; font-weight: 800; background: white; }
   765:.schedule-choice input[type="text"] { min-height: 44px; padding: 6px 8px; border: 0; border-radius: var(--radius-md); color: var(--color-text-body); font: inherit; background: rgba(255,255,255,.6); }
   766:
   767:/* World progress bar in milestones */
   768:.world-card small { color: rgba(255,255,255,.7); font-size: var(--font-size-sm); }
   769:
   770:/* ═══════════════════════════════════════════════════════════════════════
   771:   Toast
   772:   ═══════════════════════════════════════════════════════════════════════ */
   773:/* Toasts are information only, so taps pass through to the dog and buttons beneath. */
   774:.toast { position: absolute; z-index: 80; pointer-events: none; top: var(--toast-top); left: var(--overlay-center); transform: translateX(-50%); width: max-content; max-width: var(--overlay-max-width); padding: 9px 18px; border-radius: var(--radius-pill); color: white; background: var(--color-toast-bg); box-shadow: var(--shadow-toast); font-size: var(--font-size-base); font-weight: var(--font-weight-bold); animation: toast-in .2s ease-out; }
   775:
   776:@keyframes toast-in { from { transform: translate(-50%, -10px); opacity: 0; } }
   777:
   778:/* ═══════════════════════════════════════════════════════════════════════
   779:   Intro screens — cover and dedication
   780:   ═════════════════════════════════════════════════════════════════════ */
   781:
   782:.intro-cover {
   783:  position: absolute;
   784:  inset: 0;
   785:  z-index: 100;
   786:  display: flex;
   787:  align-items: center;
   788:  justify-content: center;
   789:  cursor: pointer;
   790:  background: var(--color-bg-base);
   791:  overflow: hidden;
   792:  animation: cover-rise 1.6s cubic-bezier(0.22, 0.61, 0.36, 1) both;
   793:}
   794:
   795:.intro-cover-img {
   796:  position: absolute;
   797:  inset: 0;
   798:  width: 100%;
   799:  height: 100%;
   800:  object-fit: cover;
   801:  z-index: 0;
   802:  animation: cover-zoom 8s ease-out both;
   803:}
   804:
   805:.intro-cover-veil {
   806:  position: absolute;
   807:  inset: 0;
   808:  z-index: 1;
   809:  background:
   810:    radial-gradient(ellipse at 50% 35%, rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0.18) 55%, rgba(0, 0, 0, 0.42) 100%),
   811:    linear-gradient(180deg, rgba(0, 0, 0, 0.10) 0%, rgba(0, 0, 0, 0) 30%, rgba(0, 0, 0, 0) 65%, rgba(20, 40, 28, 0.55) 100%);
   812:}
   813:
   814:.intro-cover-cta {
   815:  position: relative;
   816:  z-index: 2;
   817:  display: flex;
   818:  flex-direction: column;
   819:  align-items: center;
   820:  gap: 18px;
   821:  padding: 22px 32px;
   822:  border-radius: 999px;
   823:  background: rgba(255, 253, 247, 0.10);
   824:  backdrop-filter: blur(8px);
   825:  -webkit-backdrop-filter: blur(8px);
   826:  box-shadow: 0 8px 32px rgba(20, 40, 28, 0.25);
   827:  animation: cta-breathe 3.6s ease-in-out infinite;
   828:}
   829:
   830:.intro-cover-pulse {
   831:  position: absolute;
   832:  top: 50%;
   833:  left: 50%;
   834:  width: 180px;
   835:  height: 180px;
   836:  transform: translate(-50%, -50%);
   837:  border-radius: 50%;
   838:  background: radial-gradient(circle, rgba(255, 202, 116, 0.35) 0%, rgba(255, 202, 116, 0) 65%);
   839:  z-index: -1;
   840:  animation: pulse-ring 3s ease-out infinite;
   841:  pointer-events: none;
   842:}
   843:
   844:.intro-cover-hint {
   845:  margin: 0;
   846:  color: rgba(255, 253, 247, 0.96);
   847:  font-family: var(--font-family-base);
   848:  font-size: 16px;
   849:  font-weight: 700;
   850:  letter-spacing: 1.6px;
   851:  text-transform: uppercase;
   852:  text-shadow: 0 2px 14px rgba(18, 43, 29, 0.55);
   853:}
   854:
   855:/* Dedication — same image, gently washed, with a soft gold glow */
   856:
   857:.intro-dedication {
   858:  position: absolute;
   859:  inset: 0;
   860:  z-index: 100;
   861:  display: flex;
   862:  align-items: center;
   863:  justify-content: center;
   864:  cursor: pointer;
   865:  background: #1a2a22;
   866:  overflow: hidden;
   867:  animation: dedication-fade-in 0.25s ease-in-out both;
   868:}
   869:
   870:.intro-dedication-bg {
   871:  position: absolute;
   872:  inset: 0;
   873:  width: 100%;
   874:  height: 100%;
   875:  object-fit: cover;
   876:  filter: blur(14px) saturate(0.85) brightness(0.78);
   877:  transform: scale(1.1);
   878:  opacity: 0.55;
   879:}
   880:
   881:.intro-dedication-wash {
   882:  position: absolute;
   883:  inset: 0;
   884:  z-index: 1;
   885:  background: radial-gradient(ellipse at 50% 50%, rgba(26, 42, 34, 0.2) 0%, rgba(26, 42, 34, 0.6) 100%);
   886:}
   887:
   888:.intro-dedication-glow {
   889:  position: absolute;
   890:  top: 50%;
   891:  left: 50%;
   892:  width: 320px;
   893:  height: 320px;
   894:  transform: translate(-50%, -50%);
   895:  z-index: 2;
   896:  border-radius: 50%;
   897:  background: radial-gradient(circle, rgba(255, 202, 116, 0.18) 0%, rgba(255, 202, 116, 0) 70%);
   898:  animation: glow-breathe 4s ease-in-out infinite;
   899:  pointer-events: none;
   900:}
   901:
   902:.dedication-card {
   903:  position: relative;
   904:  z-index: 3;
   905:  display: flex;
   906:  flex-direction: column;
   907:  align-items: center;
   908:  gap: 16px;
   909:  padding: 44px 56px;
   910:  animation: dedication-card-rise 0.4s cubic-bezier(0.22, 0.61, 0.36, 1) 0.05s both;
   911:}
   912:
   913:.dedication-rule {
   914:  display: block;
   915:  width: 32px;
   916:  height: 1px;
   917:  background: linear-gradient(90deg, transparent, rgba(255, 202, 116, 0.6), transparent);
   918:}
   919:
   920:.dedication-text {
   921:  margin: 0;
   922:  font-family: var(--font-family-letter);
   923:  font-size: clamp(1.75rem, 8vw, 2.25rem);
   924:  font-weight: 400;
   925:  font-style: normal;
   926:  letter-spacing: 0;
   927:  color: rgba(255, 253, 247, 0.96);
   928:  text-shadow: 0 2px 20px rgba(20, 40, 28, 0.5);
   929:}
   930:
   931:/* Animations */
   932:
   933:@keyframes cover-rise {
   934:  from { opacity: 0; transform: scale(1.04); }
   935:  to   { opacity: 1; transform: scale(1); }
   936:}
   937:
   938:@keyframes cover-zoom {
   939:  from { transform: scale(1); }
