    21:  petName: string;
    22:}) {
    23:  const { t } = useTranslation();
    24:  const [data, setData] = useState<MilestonesResponse | null>(null);
    25:  const [loading, setLoading] = useState(true);
    26:
    27:  useEffect(() => {
    28:    api.milestones().then(setData).catch(() => {}).finally(() => setLoading(false));
    29:  }, []);
    30:
    31:  if (loading) return (
    32:    <FullCard back={back}>
    33:      <p className="supporting">Loading milestones…</p>
    34:    </FullCard>
    35:  );
    36:
    37:  const caringDays = data?.caringDays ?? pet.caringDays;
    38:
    39:  return (
    40:    <FullCard back={back}>
    41:      <p className="eyebrow green">{t("milestones.eyebrow", { name: petName })}</p>
    42:      <h2>{t("milestones.title", { count: caringDays })}</h2>
    43:      <p className="streak-line">{t("milestones.streakLine", { count: pet.streak })}</p>
    44:
    45:      {data && (
    46:        <div className="world-card">
    47:          <span className="world-level">{data.currentWorld.levelText}</span>
    48:          <h3>{data.currentWorld.label}</h3>
    49:          <p>{data.currentWorld.description}</p>
    50:          <div className="world-progress"><span style={{ width: `${data.currentWorld.progress * 100}%` }} /></div>
    51:          <small>{(data.cumulativeWalkMeters / 1000).toFixed(1)} km total walked · {data.walkCount} walks</small>
    52:        </div>
    53:      )}
    54:
    55:      <button className="customize-row" onClick={onCustomize}><span className="feature-icon"><Icon name="star" /></span><div><strong>{t("milestones.worldWardrobe")}</strong><small>{t("milestones.worldWardrobeSub", { name: petName })}</small></div><Icon name="chevron" /></button>
    56:
    57:      <div className="section-title"><h3>{t("milestones.tricks")}</h3><span>{t("milestones.tricksSub")}</span></div>
    58:      <div className="trick-grid">
    59:        {data?.tricks.map((trick) => (
    60:          <article className={trick.earned ? "earned" : ""} key={trick.name}><Icon name="star" /><strong>{trick.name}</strong><small>{trick.note}</small></article>
    61:        ))}
    62:      </div>
    63:
    64:      <div className="section-title"><h3>{t("milestones.souvenirs")}</h3><span>{t("milestones.souvenirsSub")}</span></div>
    65:      {data && data.unlockedSouvenirs.length > 0 ? data.unlockedSouvenirs.map((souvenir) => (
    66:        <button className="souvenir-row" key={souvenir.key} onClick={onWalk}>
