    68:          <div><strong>{souvenir.name}</strong><small>{souvenir.note}</small></div>
    69:          <Icon name="chevron" />
    70:        </button>
    71:      )) : (
    72:        <button className="souvenir-row" onClick={onWalk}>
    73:          <span>{data?.nextSouvenirTarget ? `${(data.nextSouvenirTarget.cumulativeMeters / 1000).toFixed(0)} km` : "—"}</span>
    74:          <div><strong>{data?.nextSouvenirTarget?.name ?? "No souvenirs yet"}</strong><small>{data?.nextSouvenirTarget?.note ?? "Walk to earn souvenirs"}</small></div>
    75:          <Icon name="chevron" />
    76:        </button>
