   175:  --top-pad: max(30px, env(safe-area-inset-top));
   176:  /* Space reserved once for the overlaid top bar and nav dock; layouts read these instead of magic offsets.
   177:     The top bar includes the toast slot under the hearts, so toasts and the tap bubble sit above a dog standing on a card. */
   178:  --top-bar-space: calc(var(--top-pad) + 112px);
   179:  --nav-space: calc(max(8px, env(safe-area-inset-bottom)) + 124px);
   180:  /* One slot for toasts and the tap-the-dog bubble: just under the name and hearts, centred over the scene. */
   181:  --toast-top: calc(var(--top-pad) + 76px);
   182:  --overlay-center: 50%;
   183:  --overlay-max-width: calc(100% - 32px);
   184:  --chip-h: 46px;
   185:  /* The dog layer may start this high, under the top bar; --top-overlap is how much of it the top bar covers. */
   186:  --stage-top: max(12px, env(safe-area-inset-top));
   187:  --top-overlap: calc(var(--top-bar-space) - var(--stage-top));
   188:  --side-gutter: 14px;
   189:  position: relative;
   190:  z-index: 1;
   191:  width: 100%;
   192:  max-width: 430px;
   193:  height: 100dvh;
   194:  margin: 0 auto;
   195:  overflow: hidden;
   196:  background: var(--color-bg-shell);
