   388:.alert-card.warm { background: var(--color-surface-cream-warm); }
   389:.alert-card small, .next-dose small, .field small { color: #9e664e; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   390:.section-title { display: flex; justify-content: space-between; align-items: center; margin: 22px 2px 12px; }
   391:.section-title h3 { margin: 0; font-size: var(--font-size-2xl); font-weight: var(--font-weight-black); }
   392:.section-title button, .section-title span { border: 0; color: var(--color-text-body); background: transparent; font-size: var(--font-size-md); font-weight: var(--font-weight-bold); }
   393:.care-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
   394:.care-grid article { display: grid; gap: 5px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-sage); }
   395:.care-grid article span { color: #5c8069; }
   396:.care-grid strong { font-size: var(--font-size-5xl); font-weight: var(--font-weight-black); }
   397:.care-grid small { color: var(--color-text-body); font-size: var(--font-size-sm); }
