   402:.activity-card { margin-top: 10px; padding: 15px; border: 1px solid var(--color-border-card); border-radius: var(--radius-3xl); }
   403:.activity-card p { margin: 0; color: var(--color-text-body); font-size: var(--font-size-md); }
   404:.activity-card p:first-child { display: flex; justify-content: space-between; margin-bottom: 5px; color: #274538; }
   405:.decision-log-card details { margin-top: 8px; color: #52685a; font-size: var(--font-size-sm); }
   406:.decision-log-card summary { cursor: pointer; font-weight: 700; }
   407:.decision-log-card dl { display: grid; grid-template-columns: 92px 1fr; gap: 5px 8px; margin: 10px 0 0; }
   408:.decision-log-card dt { font-weight: 700; text-transform: capitalize; }
   409:.decision-log-card dd { margin: 0; overflow-wrap: anywhere; }
   410:.decision-observation { display: contents; }
   411:.demo-clock-card { display: grid; gap: 9px; margin-top: 18px; padding: 16px; border: 1px solid var(--color-border-card); border-radius: var(--radius-3xl); background: #fffdf8; }
   412:.demo-clock-card h3, .demo-clock-card p { margin: 0; }
   413:.demo-clock-card > p:not(.eyebrow) { color: #78857c; font-size: var(--font-size-sm); line-height: 1.4; }
   414:.demo-clock-card label { color: #52685a; font-size: var(--font-size-sm); font-weight: 700; }
   415:.demo-clock-card input { min-height: 48px; padding: 8px 10px; border: 1px solid var(--color-border-card); border-radius: 14px; color: #294a3a; font: inherit; }
   416:.demo-clock-card select { min-height: 48px; padding: 8px 10px; border: 1px solid var(--color-border-card); border-radius: 14px; color: #294a3a; background: white; font: inherit; }
   417:.demo-clock-card .consent-toggle { display: flex; align-items: flex-start; gap: 10px; line-height: 1.35; }
   418:.demo-clock-card .consent-toggle input { width: 22px; min-height: 22px; margin: 0; accent-color: #668b70; }
   419:.demo-clock-card .primary-button { margin-top: 2px; }
   420:.role-strip { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 10px; margin-bottom: 12px; padding: 12px 14px; border-radius: var(--radius-3xl); color: #426653; background: var(--color-surface-sage-light); }
   421:.role-strip div { display: grid; }
   422:.role-strip small { color: #76847b; font-size: var(--font-size-sm); }
   423:.role-strip > span { padding: 5px 8px; border-radius: var(--radius-pill); color: #4f765e; background: white; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); }
   424:
   425:.next-dose { margin-top: 20px; background: var(--color-surface-sage-light); }
   426:.feature-icon.sage { color: var(--color-accent-sage-icon); background: var(--color-accent-sage-bg); }
