   428:/* ═══════════════════════════════════════════════════════════════════════
   429:   Timeline
   430:   ═══════════════════════════════════════════════════════════════════════ */
   431:.timeline { position: relative; display: grid; gap: 8px; }
   432:.timeline article { display: grid; grid-template-columns: 14px 54px 1fr auto; align-items: center; gap: 8px; min-height: 60px; }
   433:.timeline article:not(:last-child)::before { content: ""; position: absolute; left: 6px; height: 68px; margin-top: 66px; border-left: 2px solid var(--color-border-timeline); }
   434:.timeline-dot { z-index: 1; width: 13px; height: 13px; border: 3px solid var(--color-border-dot); border-radius: var(--radius-full); background: var(--color-surface-white); }
   435:.timeline-dot.complete { border-color: var(--color-accent-timeline); background: var(--color-accent-timeline); }
   436:.timeline time { color: var(--color-text-body); font-size: var(--font-size-sm); font-weight: var(--font-weight-bold); }
