   438:/* ═══════════════════════════════════════════════════════════════════════
   439:   Status tag / primary button
   440:   ═══════════════════════════════════════════════════════════════════════ */
   441:.status-tag { padding: 6px 9px; border-radius: var(--radius-pill); color: var(--color-status-default); background: var(--color-status-default-bg); font-size: var(--font-size-xs); font-weight: var(--font-weight-black); }
   442:.status-tag.now { color: var(--color-status-now); background: var(--color-status-now-bg); }
   443:.primary-button { width: 100%; min-height: 52px; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 18px; border: 0; border-radius: var(--radius-3xl); color: white; background: var(--color-primary); font-weight: var(--font-weight-black); text-decoration: none; cursor: pointer; box-shadow: var(--shadow-primary); }
