   445:/* ═══════════════════════════════════════════════════════════════════════
   446:   Scanner / prescription
   447:   ═══════════════════════════════════════════════════════════════════════ */
   448:.scan-card { text-align: center; }
   449:.scan-card .back-button, .scan-card .eyebrow { text-align: left; }
   450:.scan-card .supporting { margin-left: auto; margin-right: auto; }
   451:.scanner { position: relative; width: 100%; min-height: 260px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; border: 0; border-radius: var(--radius-7xl); color: #345845; background: var(--color-surface-scanner); cursor: pointer; overflow: hidden; }
   452:.scanner::before { content: ""; position: absolute; inset: 0; opacity: .4; background: repeating-linear-gradient(0deg, transparent 0 24px, rgba(76,112,86,.08) 25px 26px); }
   453:.scanner strong, .scanner small, .camera-orb { z-index: 1; }
   454:.scanner small { color: var(--color-text-body); }
   455:.camera-orb { display: grid; place-items: center; width: 64px; height: 64px; border-radius: var(--radius-full); color: white; background: var(--color-primary-camera); box-shadow: var(--shadow-camera); }
   456:.scan-corner { position: absolute; width: 42px; height: 42px; border-color: var(--color-accent-scan-corner); }
   457:.top-left { top: 18px; left: 18px; border-top: 3px solid; border-left: 3px solid; border-radius: var(--radius-sm) 0 0; }
   458:.top-right { top: 18px; right: 18px; border-top: 3px solid; border-right: 3px solid; border-radius: 0 var(--radius-sm) 0 0; }
   459:.bottom-left { bottom: 18px; left: 18px; border-bottom: 3px solid; border-left: 3px solid; border-radius: 0 0 0 var(--radius-sm); }
   460:.bottom-right { bottom: 18px; right: 18px; border-right: 3px solid; border-bottom: 3px solid; border-radius: 0 0 var(--radius-sm); }
   461:.text-button { margin-top: 16px; padding: 10px; border: 0; color: #557463; background: transparent; font-weight: var(--font-weight-black); cursor: pointer; }
   462:.prescription-result { display: grid; gap: 12px; margin-top: 20px; text-align: left; }
   463:.prescription-result > .feature-icon { width: 54px; height: 54px; border-radius: var(--radius-3xl); margin: 0 auto 8px; }
