   465:/* ═══════════════════════════════════════════════════════════════════════
   466:   Fields / proof
   467:   ═══════════════════════════════════════════════════════════════════════ */
   468:.field, .field-row { padding: 14px; border-radius: var(--radius-xl); background: var(--color-surface-sage); }
   469:.field { display: grid; gap: 3px; }
   470:.field small { color: #6e886f; }
   471:.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding: 0; background: transparent; }
   472:.proof-scanner.captured { color: #315a43; background: var(--color-surface-sage-darker); }
   473:.proof-check { z-index: 1; display: grid; place-items: center; width: 70px; height: 70px; border-radius: var(--radius-full); color: white; background: var(--color-accent-proof); box-shadow: var(--shadow-proof); }
