   475:.scanner.scanning .camera-orb { animation: pulse 1s ease-in-out infinite; }
   476:.ocr-preview { margin-top: 14px; text-align: left; padding: 10px 14px; border-radius: var(--radius-3xl); background: var(--color-surface-sage); }
   477:.ocr-preview small { color: var(--color-text-faint); font-size: var(--font-size-xs); text-transform: uppercase; letter-spacing: .04em; }
   478:.ocr-preview p { margin-top: 4px; color: var(--color-text-body); font-size: var(--font-size-sm); line-height: 1.4; }
   479:@keyframes pulse { 0%, 100% { transform: scale(1); opacity: 1; } 50% { transform: scale(1.15); opacity: .7; } }
