   481:/* ═══════════════════════════════════════════════════════════════════════
   482:   Plain card / explain points / listen button
   483:   ═══════════════════════════════════════════════════════════════════════ */
   484:.plain-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; margin-top: 20px; padding: 16px; border-radius: var(--radius-6xl); background: var(--color-surface-cream-warm); }
   485:.plain-card h3 { margin: 2px 0 0; font-size: var(--font-size-4xl); }
   486:.plain-card small { color: #9d654d; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   487:.plain-card > button { width: 46px; height: 46px; display: grid; place-items: center; border: 0; border-radius: var(--radius-full); color: white; background: var(--color-action-stop); cursor: pointer; }
   488:.explain-points { display: grid; margin-top: 14px; border: 1px solid var(--color-border-explain); border-radius: var(--radius-5xl); overflow: hidden; }
   489:.explain-points article { padding: 13px 15px; border-bottom: 1px solid var(--color-border-explain); }
   490:.explain-points article:last-child { border: 0; }
   491:.explain-points strong { font-size: var(--font-size-base); }
   492:.explain-points p { margin: 3px 0 0; color: var(--color-text-body); font-size: var(--font-size-base); line-height: 1.4; }
   493:.listen-button { width: 100%; min-height: 46px; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 12px; border: 1px solid var(--color-border-listen); border-radius: var(--radius-xl); color: #496d59; background: #f4f6f0; font-weight: var(--font-weight-black); cursor: pointer; }
   494:
   495:/* ═══════════════════════════════════════════════════════════════════════
   496:   Schedule / dog message
   497:   ═══════════════════════════════════════════════════════════════════════ */
   498:.schedule-choice { display: grid; grid-template-columns: 72px 1fr auto; align-items: center; gap: 3px 10px; margin-top: 10px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-sage); }
   499:.schedule-choice span { grid-row: span 2; color: #6b7c70; font-size: var(--font-size-md); font-weight: var(--font-weight-black); text-transform: uppercase; }
   500:.schedule-choice strong { font-size: var(--font-size-4xl); }
   501:.schedule-choice small { color: var(--color-text-body); }
   502:.schedule-choice > svg { grid-column: 3; grid-row: 1 / span 2; }
   503:.dog-message { display: flex; align-items: center; gap: 12px; margin-top: 16px; padding: 13px; border-radius: var(--radius-3xl); color: #496a57; background: var(--color-surface-cream); }
   504:.dog-message p { margin: 0; color: #6f776f; font-size: var(--font-size-md); line-height: 1.4; }
   505:.dog-message strong { color: #4a594e; }
