   507:/* ═══════════════════════════════════════════════════════════════════════
   508:   Walk screen
   509:   ═══════════════════════════════════════════════════════════════════════ */
   510:.walk-card { text-align: center; }
   511:.walk-card .back-button, .walk-card .eyebrow { text-align: left; }
   512:.walk-orb { width: 190px; height: 190px; margin: 23px auto; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; border: 10px solid var(--color-accent-walk-border-idle); border-radius: var(--radius-full); color: #446a55; background: #f2f5ed; transition: border-color .3s, transform .3s; }
   513:.walk-orb.active { border-color: var(--color-accent-walk-border); transform: scale(1.02); }
   514:.walk-orb strong { color: #193c2e; font-size: var(--font-size-8xl); font-weight: var(--font-weight-black); }
   515:.walk-orb small { color: #75847a; font-size: var(--font-size-sm); }
   516:.walk-stats { display: grid; grid-template-columns: repeat(3, 1fr); margin: 0 0 8px; }
   517:.walk-stats div { display: grid; gap: 2px; border-right: 1px solid #e0e5dc; }
   518:.walk-stats div:last-child { border: 0; }
   519:.walk-stats strong { font-size: var(--font-size-4xl); font-weight: var(--font-weight-black); }
   520:.walk-stats small { color: #79857e; font-size: var(--font-size-xs); text-transform: uppercase; }
   521:.stop-button { background: var(--color-action-stop); }
   522:.walk-note { color: #7b887f; font-size: var(--font-size-sm); }
   523:.gentle-note { margin: 8px auto 0; max-width: 330px; color: #88928b; font-size: var(--font-size-sm); line-height: 1.4; }
   524:.walk-orb.done { border-color: var(--color-accent-walk-border); }
   525:.walk-done { margin: 0 auto 12px; max-width: 330px; color: #315a43; font-size: var(--font-size-xl); font-weight: var(--font-weight-black); line-height: 1.4; }
   526:.walk-dizzy { margin: 10px auto 0; max-width: 330px; color: #9d543b; font-size: var(--font-size-sm); font-weight: var(--font-weight-bold); line-height: 1.4; }
