   528:/* ═══════════════════════════════════════════════════════════════════════
   529:   World card / customize / tricks
   530:   ═══════════════════════════════════════════════════════════════════════ */
   531:.world-card { position: relative; margin-top: 18px; padding: 22px; border-radius: var(--radius-7xl); color: white; background: linear-gradient(135deg, #4f7654, #8aa36d); overflow: hidden; }
   532:.world-card::after { content: ""; position: absolute; width: 150px; height: 150px; right: -40px; bottom: -85px; border: 18px solid rgba(255,255,255,.12); border-radius: var(--radius-full); }
   533:.world-card h3 { margin: 5px 0 2px; font-size: var(--font-size-6xl); }
   534:.world-card p { margin: 0; color: rgba(255,255,255,.78); font-size: var(--font-size-md); }
   535:.world-level { font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1.5px; }
   536:.world-progress { height: 7px; margin-top: 18px; border-radius: 9px; background: rgba(255,255,255,.22); overflow: hidden; }
   537:.world-progress span { display: block; width: 100%; height: 100%; border-radius: inherit; background: var(--color-accent-progress-bar); }
   538:.customize-row { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-top: 10px; padding: 11px; border: 0; border-radius: var(--radius-3xl); color: #315442; background: var(--color-surface-cream); text-align: left; cursor: pointer; }
   539:.customize-row div { display: grid; gap: 2px; }
   540:.customize-row small { color: #7b817b; font-size: var(--font-size-xs); }
   541:.trick-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
   542:.trick-grid article { display: grid; gap: 5px; padding: 15px; border: 1px dashed var(--color-border-trick); border-radius: var(--radius-5xl); color: #9aa29c; }
   543:.trick-grid article.earned { border: 0; color: #57735f; background: #e7efdf; }
   544:.trick-grid small { color: #818c84; font-size: var(--font-size-xs); }
