   562:.metric-card > button { min-width: 46px; height: 38px; display: grid; place-items: center; border: 0; border-radius: var(--radius-md); color: white; background: var(--color-primary-camera); font-size: var(--font-size-md); font-weight: var(--font-weight-black); cursor: pointer; }
   563:.weekly-card { margin: 12px 0; padding: 17px; border-radius: var(--radius-6xl); background: var(--color-surface-sage); }
   564:.weekly-card .card-heading { margin-bottom: 10px; }
