   585:.summary-score strong { font-size: var(--font-size-5xl); }
   586:.summary-score span { font-size: var(--font-size-sm); font-weight: var(--font-weight-black); }
   587:.summary-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; margin-top: 10px; }
   588:.summary-grid article { display: grid; gap: 3px; padding: 14px; border-radius: var(--radius-2xl); background: var(--color-surface-fog); }
   589:.summary-grid strong { font-size: var(--font-size-4xl); }
   590:.summary-grid small { color: #79857d; font-size: var(--font-size-xs); }
   591:.doctor-question { display: flex; align-items: center; gap: 12px; margin-top: 10px; padding: 14px; border-radius: var(--radius-3xl); color: #805b46; background: var(--color-surface-cream); }
   592:.doctor-question small { font-size: var(--font-size-2xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   593:.doctor-question p { margin: 3px 0 0; font-size: var(--font-size-md); }
   594:
   595:/* ═══════════════════════════════════════════════════════════════════════
   596:   Settings
   597:   ═══════════════════════════════════════════════════════════════════════ */
   598:.settings-group { display: grid; gap: 9px; margin-top: 18px; }
   599:.settings-group > button { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; padding: 12px; border: 0; border-radius: var(--radius-3xl); color: #294a3a; background: var(--color-surface-sage); text-align: left; cursor: pointer; }
   600:.settings-group > button:nth-child(1) { background: var(--color-surface-cream-alt); }
   601:.settings-group button div { display: grid; gap: 2px; }
   602:.settings-group small { color: #78857c; font-size: var(--font-size-sm); }
   603:.settings-note { display: flex; align-items: center; gap: 12px; margin-top: 14px; padding: 13px; border-radius: var(--radius-2xl); color: #65766b; background: var(--color-surface-stone-alt); }
   604:.settings-note p { margin: 0; font-size: var(--font-size-sm); line-height: 1.4; }
   605:
   606:/* ═══════════════════════════════════════════════════════════════════════
   607:   World picker / wardrobe
   608:   ═══════════════════════════════════════════════════════════════════════ */
   609:.world-picker { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
   610:.world-picker > button { min-width: 0; display: grid; gap: 3px; padding: 6px 6px 9px; border: 2px solid transparent; border-radius: var(--radius-3xl); color: #345343; background: var(--color-surface-stone); text-align: left; cursor: pointer; }
   611:.world-picker > button.selected { border-color: var(--color-border-world-sel); background: var(--color-surface-sage-light); }
   612:.world-picker strong { padding-inline: 3px; overflow: hidden; font-size: var(--font-size-md); text-overflow: ellipsis; white-space: nowrap; }
   613:.world-picker small { padding-inline: 3px; overflow: hidden; color: var(--color-text-faint); font-size: var(--font-size-2xs); text-overflow: ellipsis; white-space: nowrap; }
   614:
   615:.world-thumb { position: relative; height: 58px; border-radius: var(--radius-md); overflow: hidden; }
   616:.world-thumb::before, .world-thumb::after, .world-thumb i { content: ""; position: absolute; display: block; }
   617:.flat .world-thumb { background: linear-gradient(#f7c78f 0 48%, #c98555 49% 52%, #e7d3b5 53%); }
   618:.flat .world-thumb::before { left: 13%; bottom: 9px; width: 62%; height: 24px; border-radius: var(--radius-sm) var(--radius-sm) 3px 3px; background: #8caa82; }
   619:.flat .world-thumb::after { right: 10px; top: 8px; width: 17px; height: 24px; border: 3px solid rgba(255,255,255,.8); }
   620:.garden .world-thumb { background: linear-gradient(#8dc8c1 0 46%, #6b9f5b 47% 70%, #89b662 71%); }
   621:.garden .world-thumb::before { left: 11px; top: 13px; width: 22px; height: 31px; border-radius: var(--radius-full); background: #3f7b47; box-shadow: 45px 7px 0 #e194a4; }
   622:.garden .world-thumb::after { left: 42%; bottom: 0; width: 16%; height: 31px; background: #d6bf83; clip-path: polygon(40% 0,60% 0,100% 100%,0 100%); }
   623:.kampung .world-thumb { background: linear-gradient(#f5a86e 0 48%, #617d47 49%); }
   624:.kampung .world-thumb::before { left: 24%; bottom: 9px; width: 54%; height: 27px; background: #e6c184; clip-path: polygon(50% 0,100% 35%,92% 35%,92% 100%,8% 100%,8% 35%,0 35%); }
   625:.kampung .world-thumb::after { left: 44%; bottom: 9px; width: 14%; height: 16px; background: #855943; }
   626:.wardrobe-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
   627:.wardrobe-grid button { display: grid; grid-template-columns: 45px 1fr; align-items: center; gap: 1px 8px; padding: 9px; border: 2px solid transparent; border-radius: var(--radius-2xl); color: #345343; background: var(--color-surface-stone); text-align: left; cursor: pointer; }
   628:.wardrobe-grid button.selected { border-color: var(--color-border-wardrobe-sel); background: var(--color-surface-cream-selected); }
   629:.wardrobe-grid button > span { grid-row: span 2; display: grid; place-items: center; width: 43px; height: 43px; border-radius: var(--radius-xl); color: #6b826f; background: white; }
   630:.wardrobe-grid strong { font-size: var(--font-size-sm); }
   631:.wardrobe-grid small { color: var(--color-text-faint); font-size: var(--font-size-2xs); }
   632:
   633:/* ═══════════════════════════════════════════════════════════════════════
   634:   Accessory marks (mini icons in wardrobe)
   635:   ═══════════════════════════════════════════════════════════════════════ */
   636:.accessory-mark { position: relative; display: block; width: 34px; height: 26px; }
   637:.mark-glasses i { position: absolute; top: 7px; width: 14px; height: 11px; border: 4px solid #27322b; border-radius: var(--radius-full); }
   638:.mark-glasses i:first-child { left: 0; }
   639:.mark-glasses i:last-child { right: 0; }
   640:.mark-glasses::after { content: ""; position: absolute; top: 12px; left: 14px; width: 7px; border-top: 3px solid #27322b; }
   641:.mark-hat::before { content: ""; position: absolute; left: 5px; top: 3px; width: 24px; height: 16px; border-radius: 15px 15px 3px 3px; background: #e4b85e; }
   642:.mark-hat::after { content: ""; position: absolute; left: 0; top: 17px; width: 34px; height: 7px; border-radius: var(--radius-full); background: #bd793f; }
   643:.mark-flower::before { content: ""; position: absolute; left: 10px; top: 5px; width: 14px; height: 14px; border-radius: 50%; background: #e8a5c0; box-shadow: -4px 0 #d484a8, 4px 0 #d484a8, 0 -4px #d484a8, 0 4px #d484a8; }
   644:.mark-flower::after { content: ""; position: absolute; left: 14px; top: 9px; width: 6px; height: 6px; border-radius: 50%; background: #f5d76e; }
   645:
   646:/* ═══════════════════════════════════════════════════════════════════════
   647:   Pet accessories (full-size on the dog)
   648:   ═══════════════════════════════════════════════════════════════════════ */
   649:/* Rendered inside DogStage's body, so it moves with the dog.
   650:   Sizes and positions are driven by config/accessories.ts via CSS custom properties. */
   651:.pet-accessory {
   652:  position: absolute;
   653:  z-index: 1;
   654:  left: var(--acc-left, 50%);
   655:  top: var(--acc-top);
   656:  width: var(--acc-width);
   657:  height: var(--acc-height);
   658:  transform: translateX(-50%) rotate(var(--acc-rotate, 0deg));
   659:  pointer-events: none;
   660:}
   661:
   662:.accessory-glasses i {
   663:  position: absolute;
   664:  width: 41%;
   665:  height: 78%;
   666:  border: min(8px, 1.5cqw) solid #201f1d;
   667:  border-radius: var(--radius-full);
   668:  background: rgba(47,57,50,.48);
   669:  box-shadow: inset 0 3px rgba(255,255,255,.25);
   670:}
   671:.accessory-glasses i:first-child { left: 4%; }
   672:.accessory-glasses i:last-child { right: 4%; }
   673:.accessory-glasses::after {
   674:  content: "";
   675:  position: absolute;
   676:  top: 33%;
   677:  left: 43%;
   678:  width: 15%;
   679:  border-top: min(7px, 1.2cqw) solid #201f1d;
   680:}
   681:
   682:.accessory-hat::before {
   683:  content: "";
   684:  position: absolute;
   685:  left: 23%;
   686:  top: 6%;
   687:  width: 55%;
   688:  height: 69%;
   689:  border-radius: 999px 999px 8px 8px;
   690:  background: repeating-linear-gradient(90deg,#e7bd65 0 5px,#d7a953 6px 8px);
   691:}
   692:.accessory-hat::after {
   693:  content: "";
   694:  position: absolute;
   695:  left: 0;
   696:  bottom: 6%;
   697:  width: 100%;
   698:  height: 29%;
   699:  border-radius: var(--radius-full);
   700:  background: #c88143;
   701:  box-shadow: inset 0 5px #f0ce79;
   702:}
   703:
   704:.accessory-flower::before {
   705:  content: "";
   706:  position: absolute;
   707:  left: 20%;
   708:  top: 20%;
   709:  width: 60%;
   710:  height: 60%;
   711:  border-radius: 50%;
   712:  background: #e8a5c0;
   713:  box-shadow: -20% 0 #d484a8, 20% 0 #d484a8, 0 -20% #d484a8, 0 20% #d484a8;
   714:}
   715:.accessory-flower::after {
   716:  content: "";
   717:  position: absolute;
   718:  left: 35%;
   719:  top: 35%;
   720:  width: 30%;
   721:  height: 30%;
   722:  border-radius: 50%;
   723:  background: #f5d76e;
   724:}
   725:
   726:/* ═══════════════════════════════════════════════════════════════════════
   727:   T2: Search bar, HSA results, medication edit, explanation links
   728:   ═══════════════════════════════════════════════════════════════════════ */
   729:.search-bar { display: flex; gap: 8px; margin-top: 16px; }
   730:.search-bar input { flex: 1; min-height: 48px; padding: 8px 12px; border: 1px solid var(--color-border-card); border-radius: var(--radius-xl); color: var(--color-text-base); font: inherit; }
   731:.search-bar input:focus { outline: 2px solid var(--color-focus); outline-offset: 1px; }
   732:.hsa-results { display: grid; gap: 6px; margin-top: 14px; text-align: left; }
   733:.hsa-result-row { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 8px; padding: 12px 14px; border: 0; border-radius: var(--radius-3xl); color: var(--color-text-heading); background: var(--color-surface-sage); text-align: left; cursor: pointer; }
   734:.hsa-result-row:hover { background: var(--color-surface-sage-dark); }
   735:.hsa-result-row strong { font-size: var(--font-size-lg); }
   736:.hsa-result-row small { display: block; color: var(--color-text-body); font-size: var(--font-size-sm); }
   737:.hsa-credit { margin-top: 12px; color: var(--color-text-faint); font-size: var(--font-size-xs); line-height: 1.4; text-align: left; }
   738:.no-results { text-align: center; margin-top: 18px; }
   739:.no-results p { color: var(--color-text-body); font-size: var(--font-size-lg); }
   740:.error-text { margin-top: 8px; color: var(--color-action-stop); font-size: var(--font-size-sm); font-weight: 700; }
   741:.field-hint { color: var(--color-text-faint) !important; font-size: var(--font-size-xs) !important; font-weight: 400 !important; letter-spacing: 0 !important; }
   742:.field input { min-height: 44px; padding: 6px 10px; border: 1px solid var(--color-border-card); border-radius: var(--radius-lg); color: var(--color-text-base); font: inherit; }
   743:.field input:focus { outline: 2px solid var(--color-focus); outline-offset: 1px; }
   744:
   745:/* Medication list and edit on /care */
   746:.medication-list { display: grid; gap: 6px; }
   747:.medication-edit-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 12px 14px; border-radius: var(--radius-3xl); background: var(--color-surface-sage); }
   748:.medication-edit-row strong { font-size: var(--font-size-lg); }
   749:.medication-edit-row small { color: var(--color-text-body); font-size: var(--font-size-sm); }
   750:.medication-edit-form { display: grid; gap: 6px; width: 100%; }
   751:.medication-edit-form label { color: var(--color-text-body); font-size: var(--font-size-sm); font-weight: 700; }
   752:.medication-edit-form input { min-height: 44px; padding: 6px 10px; border: 1px solid var(--color-border-card); border-radius: var(--radius-lg); color: var(--color-text-base); font: inherit; }
   753:.edit-actions { display: flex; gap: 8px; margin-top: 4px; }
   754:.edit-actions .primary-button { margin-top: 0; min-height: 40px; flex: 1; }
   755:.edit-actions .text-button { margin-top: 0; }
   756:
   757:/* Explanation links and credits */
   758:.explanation-links { margin-top: 16px; display: grid; gap: 8px; }
   759:.source-credit { color: var(--color-text-faint); font-size: var(--font-size-xs); margin: 0; }
   760:.external-link { display: flex; align-items: center; gap: 6px; padding: 10px 12px; border: 1px solid var(--color-border-card); border-radius: var(--radius-xl); color: var(--color-text-heading); text-decoration: none; font-size: var(--font-size-sm); font-weight: 700; }
   761:.external-link:hover { background: var(--color-surface-sage); }
   762:
   763:/* Schedule choices with time inputs */
   764:.schedule-choice input[type="time"] { min-height: 44px; padding: 6px 8px; border: 0; border-radius: var(--radius-md); color: var(--color-text-heading); font: inherit; font-weight: 800; background: white; }
   765:.schedule-choice input[type="text"] { min-height: 44px; padding: 6px 8px; border: 0; border-radius: var(--radius-md); color: var(--color-text-body); font: inherit; background: rgba(255,255,255,.6); }
   766:
   767:/* World progress bar in milestones */
   768:.world-card small { color: rgba(255,255,255,.7); font-size: var(--font-size-sm); }
   769:
   770:/* ═══════════════════════════════════════════════════════════════════════
   771:   Toast
   772:   ═══════════════════════════════════════════════════════════════════════ */
   773:/* Toasts are information only, so taps pass through to the dog and buttons beneath. */
   774:.toast { position: absolute; z-index: 80; pointer-events: none; top: var(--toast-top); left: var(--overlay-center); transform: translateX(-50%); width: max-content; max-width: var(--overlay-max-width); padding: 9px 18px; border-radius: var(--radius-pill); color: white; background: var(--color-toast-bg); box-shadow: var(--shadow-toast); font-size: var(--font-size-base); font-weight: var(--font-weight-bold); animation: toast-in .2s ease-out; }
   775:
   776:@keyframes toast-in { from { transform: translate(-50%, -10px); opacity: 0; } }
   777:
   778:/* ═══════════════════════════════════════════════════════════════════════
   779:   Intro screens — cover and dedication
   780:   ═════════════════════════════════════════════════════════════════════ */
   781:
   782:.intro-cover {
   783:  position: absolute;
   784:  inset: 0;
   785:  z-index: 100;
   786:  display: flex;
   787:  align-items: center;
   788:  justify-content: center;
   789:  cursor: pointer;
   790:  background: var(--color-bg-base);
   791:  overflow: hidden;
   792:  animation: cover-rise 1.6s cubic-bezier(0.22, 0.61, 0.36, 1) both;
   793:}
   794:
   795:.intro-cover-img {
   796:  position: absolute;
   797:  inset: 0;
   798:  width: 100%;
   799:  height: 100%;
   800:  object-fit: cover;
   801:  z-index: 0;
   802:  animation: cover-zoom 8s ease-out both;
   803:}
   804:
   805:.intro-cover-veil {
   806:  position: absolute;
   807:  inset: 0;
   808:  z-index: 1;
   809:  background:
   810:    radial-gradient(ellipse at 50% 35%, rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0.18) 55%, rgba(0, 0, 0, 0.42) 100%),
   811:    linear-gradient(180deg, rgba(0, 0, 0, 0.10) 0%, rgba(0, 0, 0, 0) 30%, rgba(0, 0, 0, 0) 65%, rgba(20, 40, 28, 0.55) 100%);
   812:}
   813:
   814:.intro-cover-cta {
   815:  position: relative;
   816:  z-index: 2;
   817:  display: flex;
   818:  flex-direction: column;
   819:  align-items: center;
   820:  gap: 18px;
   821:  padding: 22px 32px;
   822:  border-radius: 999px;
   823:  background: rgba(255, 253, 247, 0.10);
   824:  backdrop-filter: blur(8px);
   825:  -webkit-backdrop-filter: blur(8px);
   826:  box-shadow: 0 8px 32px rgba(20, 40, 28, 0.25);
   827:  animation: cta-breathe 3.6s ease-in-out infinite;
   828:}
   829:
   830:.intro-cover-pulse {
   831:  position: absolute;
   832:  top: 50%;
   833:  left: 50%;
   834:  width: 180px;
   835:  height: 180px;
   836:  transform: translate(-50%, -50%);
   837:  border-radius: 50%;
   838:  background: radial-gradient(circle, rgba(255, 202, 116, 0.35) 0%, rgba(255, 202, 116, 0) 65%);
   839:  z-index: -1;
   840:  animation: pulse-ring 3s ease-out infinite;
   841:  pointer-events: none;
   842:}
   843:
   844:.intro-cover-hint {
   845:  margin: 0;
   846:  color: rgba(255, 253, 247, 0.96);
   847:  font-family: var(--font-family-base);
   848:  font-size: 16px;
   849:  font-weight: 700;
   850:  letter-spacing: 1.6px;
   851:  text-transform: uppercase;
   852:  text-shadow: 0 2px 14px rgba(18, 43, 29, 0.55);
   853:}
   854:
   855:/* Dedication — same image, gently washed, with a soft gold glow */
   856:
   857:.intro-dedication {
   858:  position: absolute;
   859:  inset: 0;
   860:  z-index: 100;
   861:  display: flex;
   862:  align-items: center;
   863:  justify-content: center;
   864:  cursor: pointer;
   865:  background: #1a2a22;
   866:  overflow: hidden;
   867:  animation: dedication-fade-in 0.25s ease-in-out both;
   868:}
   869:
   870:.intro-dedication-bg {
   871:  position: absolute;
   872:  inset: 0;
   873:  width: 100%;
   874:  height: 100%;
   875:  object-fit: cover;
   876:  filter: blur(14px) saturate(0.85) brightness(0.78);
   877:  transform: scale(1.1);
   878:  opacity: 0.55;
   879:}
   880:
   881:.intro-dedication-wash {
   882:  position: absolute;
   883:  inset: 0;
   884:  z-index: 1;
   885:  background: radial-gradient(ellipse at 50% 50%, rgba(26, 42, 34, 0.2) 0%, rgba(26, 42, 34, 0.6) 100%);
   886:}
   887:
   888:.intro-dedication-glow {
   889:  position: absolute;
   890:  top: 50%;
   891:  left: 50%;
   892:  width: 320px;
   893:  height: 320px;
   894:  transform: translate(-50%, -50%);
   895:  z-index: 2;
   896:  border-radius: 50%;
   897:  background: radial-gradient(circle, rgba(255, 202, 116, 0.18) 0%, rgba(255, 202, 116, 0) 70%);
   898:  animation: glow-breathe 4s ease-in-out infinite;
   899:  pointer-events: none;
   900:}
   901:
   902:.dedication-card {
   903:  position: relative;
   904:  z-index: 3;
   905:  display: flex;
   906:  flex-direction: column;
   907:  align-items: center;
   908:  gap: 16px;
   909:  padding: 44px 56px;
   910:  animation: dedication-card-rise 0.4s cubic-bezier(0.22, 0.61, 0.36, 1) 0.05s both;
   911:}
   912:
   913:.dedication-rule {
   914:  display: block;
   915:  width: 32px;
   916:  height: 1px;
   917:  background: linear-gradient(90deg, transparent, rgba(255, 202, 116, 0.6), transparent);
   918:}
   919:
   920:.dedication-text {
   921:  margin: 0;
   922:  font-family: var(--font-family-letter);
   923:  font-size: clamp(1.75rem, 8vw, 2.25rem);
   924:  font-weight: 400;
   925:  font-style: normal;
   926:  letter-spacing: 0;
   927:  color: rgba(255, 253, 247, 0.96);
   928:  text-shadow: 0 2px 20px rgba(20, 40, 28, 0.5);
   929:}
   930:
   931:/* Animations */
   932:
   933:@keyframes cover-rise {
   934:  from { opacity: 0; transform: scale(1.04); }
   935:  to   { opacity: 1; transform: scale(1); }
   936:}
   937:
   938:@keyframes cover-zoom {
   939:  from { transform: scale(1); }
   940:  to   { transform: scale(1.08); }
   941:}
   942:
   943:@keyframes cta-breathe {
   944:  0%, 100% { transform: scale(1); opacity: 0.92; }
   945:  50%      { transform: scale(1.04); opacity: 1; }
   946:}
   947:
   948:@keyframes pulse-ring {
   949:  0%   { transform: translate(-50%, -50%) scale(0.6); opacity: 0.8; }
   950:  100% { transform: translate(-50%, -50%) scale(1.4); opacity: 0; }
   951:}
   952:
   953:@keyframes dedication-fade-in {
   954:  from { opacity: 0; }
   955:  to   { opacity: 1; }
   956:}
   957:
   958:@keyframes dedication-card-rise {
   959:  from { opacity: 0; transform: translateY(12px); }
   960:  to   { opacity: 1; transform: translateY(0); }
   961:}
   962:
   963:@keyframes glow-breathe {
   964:  0%, 100% { opacity: 0.6; transform: translate(-50%, -50%) scale(1); }
   965:  50%      { opacity: 1; transform: translate(-50%, -50%) scale(1.1); }
   966:}
   967:
   968:@media (prefers-reduced-motion: reduce) {
   969:  .intro-cover,
   970:  .intro-cover-img,
   971:  .intro-cover-cta,
   972:  .intro-cover-pulse,
   973:  .intro-dedication,
   974:  .intro-dedication-glow,
   975:  .dedication-card {
   976:    animation: none !important;
   977:  }
   978:  .dedication-card {
   979:    opacity: 1;
   980:    transform: none;
   981:  }
   982:  .intro-dedication {
   983:    opacity: 1;
   984:  }
